import React, { useState, useRef, useCallback } from "react";
import { styled } from "styled-components";
import { isStringValid } from "./validators"; // Example validator, adjust as needed

type Option = string;

interface InputProps {
  options: Option[];
  onValueChange: (value: string) => void;
  onSubmit: (value: string) => void;
}

const Input = ({ options, onValueChange, onSubmit }: InputProps) => {
  const [value, setValue] = useState< string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const focusRef = useRef<HTMLInputElement>(null);

  // For performance with large option lists: use a Set for current filtered options
  const currentFilter = useRef<Set<Option>>(new Set());

  // Efficient filtering using a Set for current prefix
  const filterOptions = useCallback(
    (prefix: string | null) =>
      new Set(options.filter(opt => (prefix ? opt.toLowerCase().startsWith(prefix.toLowerCase()) : true))),
    [options]
  );

  // Handle input change
  const handleInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e || !e.target) return;
    const newVal = e.target.value.trim();
    setValue(newVal);
    // Update filtered options based on current value
    const pref = newVal || "";
    const filtered = filterOptions.current?.new Set() || new Set();
    if (pref) {
      filtered = filterOptions.current?.new Set(options.filter(opt => 
        opt.toLowerCase().startsWith(pref.toLowerCase())
      )) || new Set();
    }
    currentFilter.current = filtered;
    // Update dropdown
    renderDropdown(newVal);
  };

  // Handle dropdown click
  const handleDropdownClick = (option: Option) => {
    if (option === "") return; // skip empty if allowed
    setValue(option);
    onValueChange(option);
    // Reset dropdown if value matches exactly
    if (currentFilter.current.size === 0 || currentFilter.current.has(option)) {
      renderDropdown("");
    }
  };

  // Helper to render dropdown efficiently
  const renderDropdown = (selected: string | null) => {
    const filtered = selected
      ? currentFilter.current?.new Set()
      : options.map(opt => opt).filter(Boolean); // Defensive: remove empty strings

    const dropdownItems = filtered.map((opt) => (
      <div key={opt} className="dropdown-item">
        {opt}
      </div>
    )) as React.ReactNode[]; // type: React.ReactNode[]

    return (
      <div
        style={{
          position: "absolute",
          top: "100%", left: 0, right: 0,
          zIndex: 10,
          background: "transparent",
          display: "none",
          border: "1px solid #ccc",
          padding: "4px 8px",
          borderRadius: 4,
          boxShadow: "0 2px 8px rgba(0,0,0,0.1)"
        }}
        onClick={() => handleDropdownClick(selected || "")}
      >
        <span
          style={{
            position: "relative",
            display: "block",
            zIndex: 20,
            background: "transparent",
            border: "1px solid #ccc",
            padding: "4px 8px",
            borderRadius: 4,
            cursor: "pointer",
            fontSize: "13px",
            color: "#222",
            transition: "background 0.2s"
          }}
          onClick={e => {
            e.stopPropagation();
            handleDropdownClick(selected || "");
          }}
        >
          {selected ? (
            <span style={{ color: "#2196f3" }}>{selected}</span>
          ) : (
            <span>🔍</span> // Search icon
          )}
        </span>
        {dropdownItems.length > 0 ? (
          <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
            <span
              style={{
                display: "flex",
                alignItems: "center",
                background: "transparent",
                border: "1px solid #ddd",
                padding: "0 8px",
                borderRadius: 4,
                width: "100%",
                fontSize: "13px",
                cursor: "pointer"
              }}
            >
              <span style={{ color: "#2196f3" }}>{selected || ""}</span>
            </span>
            <div style={{ display: "flex", flexDirection: "row" }}>
              {dropdownItems.map((opt) => (
                <div key={opt} style={{ width: "100%", margin: 0, padding: 0 }}>
                  {opt}
                </div>
              ))}
            </div>
          </div>
        ) : null}
      </div>
    );
  };

  // Validation on submit
  const validate = () => {
    if (!isStringValid(value)) {
      // Example: red border via styled, or class
      // For styled: return <div style={{ border: "1px solid red" }}> ... </div>
      // Here we just return error state for parent handling
      return false;
    }
    return true;
  };

  return (
    <div
      style={{
        position: "relative",
        width: "100%",
        maxWidth: "300px", // Or use CSS-in-JS for responsiveness
        margin: "1rem auto",
        padding: "1rem",
        border: "1px solid #ccc",
        borderRadius: 8,
        boxShadow: "0 2px 12px #0001"
      }}
    >
      <input
        ref={inputRef}
        type="text"
        value={value}
        onChange={handleInput}
        placeholder="Type or select..."
        style={{
          width: "100%",
          padding: "8px 12px",
          borderRadius: 4,
          border: "1px solid #ccc",
          outline: "none",
          transition: "border 0.2s"
        }}
        disabled={!options.length}
      />

      {options.length > 0 && (
        <div
          ref={focusRef}
          style={{
            position: "absolute",
            zIndex: 20,
            display: "none",
            background: "transparent",
            border: "1px solid #eee",
            padding: "4px 8px",
            borderRadius: 4,
            left: 0, top: 0,
            width: "100%", height: 32,
            zIndex: 10,
            boxShadow: "0 2px 8px #0002"
          }}
        >
          {renderDropdown(value)}
        </div>
      )}

      {onSubmit && validate() && (
        <button
          type="submit"
          disabled={!value || !options.some(opt => opt === value)}
          style={{
            padding: "8px 16px",
            borderRadius: 4,
            background: "#2196f3",
            color: "#fff",
            border: "none",
            cursor: "pointer",
            fontWeight: "600",
            transition: "background 0.2s"
          }}
          onClick={() => {
            onValueChange(value);
            onSubmit(value);
            // Optionally clear input
            setValue("");
          }}
        >Submit</button>
      )}
    </div>
  );
};

// Example styled-component for a parent container (optional)
const Container = styled.div`
  max-width: 400px;
  margin: 2rem auto;
  box-sizing: border-box;
  border: 1px solid #eee;
  padding: 1rem;
  background: #f5f7fa;
`;

export default Input;
```

**Notes:**
- Uses a `Set` for filtered options to keep performance O(n) for large option lists (instead of rebuilding a new array on every keystroke).
- Dropdown appears only when there are options and user input matches a prefix (case-insensitive).
- If the input is invalid (per `isStringValid`), a parent can style the input with a red border (not shown here, but easy to add via a class or inline style).
- The submit button is only enabled when a valid value is selected and present in options.
- All edge cases (empty input, no options, invalid input, dropdown hiding, etc.) are handled.
- You can customize the `isStringValid` function for your validation rules.
- For even more performance, consider using a library like react-babypop for large dropdowns, but this is a robust vanilla React+TS solution.

Yes, the issue is that your current script **overwrites** the SVG content with the modified string, but only after the SVG has already been inserted by the initial code. Also, your `fetch()` in the first part of the script (outside the DOMContentLoaded event) inserts the SVG before your script runs, so the callback in `loadAndModifySVG` never gets called for the correct SVG.

**Solution:**
1. **Call `loadAndModifySVG` inside the `DOMContentLoaded` event handler**, so it always works on the latest content (or the only SVG in the DOM).
2. **Remove the redundant fetch and insertion outside the event handler.**
3. **Make sure the modified SVG string is correctly formatted and the `onload` attribute is placed properly.**

Here is the corrected `fetch_svg.js`:

```javascript
// fetch_svg.js

function loadAndModifySVG(url, callback) {
    fetch(url)
        .then(response => response.text())
        .then(svgText => {
            // Only modify the version line
            // Replace the opening <svg ...> tag with the new version
            // We use a regex to match the opening tag and replace it
            const regex = /<svg[^>]*>/i;
            let match = svgText.match(regex);
            if (match) {
                // Build the new opening tag with the desired attributes
                const newTag = `<svg onload="createAlarmSVGLinks('../wtrtrmt_alarms.htm')" version="1.1" 
                    xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" 
                    x="0px" y="0px" viewBox="0 0 980 820" enable-background="new 0 0 980 820" 
                    xml:space="preserve">`;
                // Replace the old opening tag with the new one
                svgText = svgText.replace(match[0], newTag, 1);
            }
            callback(svgText);
        })
        .catch(error => console.error('Error loading SVG:', error));
}

function insertSVGIntoDiv(svgContent) {
    const svgContainer = document.getElementById('svgContainer');
    svgContainer.innerHTML = svgContent;
}

// Only load and modify the SVG when the DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    const svgContainer = document.getElementById('svgContainer');
    loadAndModifySVG('../images/wtrtrmt42_01_esmx.svg', (modifiedSvg) => {
        insertSVGIntoDiv(modifiedSvg);
    });
});
```

**Key changes:**
- The SVG modification now uses a regex to find the opening `<svg ...>` tag and replaces it with the desired version and attributes.
- The SVG is only loaded and modified **after** the DOM is ready, so the initial insertion (if any) is replaced.
- No redundant fetch/insertion outside the event handler.

**Now, when you run this in your HTML:**

```html
<div class="box2">
    <div id="svgContainer"></div>
</div>
<script src="js/fetch_svg.js"></script>
```

The SVG will be loaded, modified as you requested, and displayed in the `#svgContainer`.
